<template>
  <div class="vote_statistics_box"  v-loading="loading">
    <div class="vote_statistics_top">
        <div style="float: left;" @click="return_vote_list">
          <i class="el-icon-arrow-left"></i>&nbsp;&nbsp;返回投票列表
        </div>
        【{{vote_detail['vote_title']}}】统计
    </div>
    <div class="vote_statistics_content">
      <div class="vote_statistics_title">
        <el-row>
          <el-col :span="18">
            <span  style="color: #2782F4;" v-if="vote_detail['vote_number']>0"> 共{{vote_detail['vote_number']}}人参与投票</span>
            <span v-if="vote_detail['vote_number']<=0"> 暂时无人参与投票</span>
            <span v-if="limit_type==vote_detail.limit_type">(由于该投票仅针对业主，所以统计时不仅计算参与人数比，还统计业主的专有部分面积比)</span>
            <span v-if="limit_type!=vote_detail.limit_type">(由于该投票是针对小区内所有住户，所以投票结果仅统计参与人数比)</span>
          </el-col>
          <el-col :span="6" class="vote_statistics_export">
            <el-button type="primary" size="medium" plain @click="export_vote">导出</el-button>
          </el-col>
        </el-row>
      </div>
      <div class="vote_statistics_vote_content">
        <div class="vote_content" v-for="(item, index) in vote_detail.vote_block">
          <div class="vote_title">
            <span class="vote_sort">{{vote_sort(index)}}.</span>
            <span class="title_info">{{item.block_title}}</span>
            <span class="real_num_info" style="color: #00bf5a;" v-if="4==item.block_type && item.block_number>0">
                (实际{{item.block_number}}人参与)
            </span>
            <span>
              &nbsp;&nbsp;&nbsp;<el-button type="primary" size="mini" plain @click="look_detail(item.block_id)">查看详细信息</el-button>
            </span>
          </div>
          <div class="vote_statistics_data table_info" v-if="(3==item.block_type || 4==item.block_type) && item.info_options && limit_type!=vote_detail.limit_type">
            <el-table
              :data="item.info_options"
              show-summary
              :data-block_number="item.block_number"
              :summary-method="getSummaries"
              style="width: 100%;text-align: center;">
              <el-table-column
                label="选项"
                min-width="180">
                <template slot-scope="scope">
                  <span>{{ scope.row.option_name }}</span>
                </template>
              </el-table-column>
              <el-table-column
                label="小计"
                min-width="100">
                <template slot-scope="scope">
                  <span>{{ scope.row.option_number }}</span>
                </template>
              </el-table-column>
              <el-table-column
                label="比例"
                min-width="200">
                <template slot-scope="scope">
                  <span>
                    <el-progress :text-inside="true" :stroke-width="18" :percentage="proportion_num(scope.row.proportion)"></el-progress>
                  </span>
                </template>
              </el-table-column>
            </el-table>
          </div>

          <div class="vote_statistics_data table_info" v-if="(3==item.block_type || 4==item.block_type) && item.info_options && limit_type==vote_detail.limit_type">
            <el-table
              :data="item.info_options"
              show-summary
              :data-block_number="item.block_number"
              :summary-method="getSummaries"
              style="width: 100%;text-align: center;">
              <el-table-column
                label="选项"
                min-width="180">
                <template slot-scope="scope">
                  <span>{{ scope.row.option_name }}</span>
                </template>
              </el-table-column>
              <el-table-column
                label="小计"
                min-width="100">
                <template slot-scope="scope">
                  <span>{{ scope.row.option_number }}</span>
                </template>
              </el-table-column>
              <el-table-column
                label="参与业主投票比例"
                min-width="200">
                <template slot-scope="scope">
                  <span>
                    <span>{{scope.row.option_number}}</span><span>/</span><span>{{item.block_number}}</span>
                    <span>({{scope.row.proportion}}%)</span>
                  </span>
                </template>
              </el-table-column>
              <el-table-column
                label="小区总业主投票比例"
                min-width="200">
                <template slot-scope="scope">
                  <span>
                    <span>{{scope.row.option_number}}</span><span>/</span><span>{{item.owner_total}}</span>
                    <span>({{scope.row.proportion_total}}%)</span>
                  </span>
                </template>
              </el-table-column>
              <el-table-column
                label="参与业主有效面积比例"
                min-width="200">
                <template slot-scope="scope">
                  <span>
                    <span>{{scope.row.option_house_size_total}}㎡</span><span>/</span><span>{{item.block_house_size_total}}㎡</span>
                    <span>({{scope.row.option_house_size_proportion}}%)</span>
                  </span>
                </template>
              </el-table-column>
              <el-table-column
                label="所有业主有效面积比例"
                min-width="200">
                <template slot-scope="scope">
                  <span>
                    <span>{{scope.row.option_house_size_total}}㎡</span><span>/</span><span>{{item.owner_house_size_total}}㎡</span>
                    <span>({{scope.row.option_house_size_proportion_total}}%)</span>
                  </span>
                </template>
              </el-table-column>
            </el-table>
          </div>



          <div class="vote_statistics_data" v-if="5==item.block_type">
            <div class="vote_score_title" v-if="item.block_number>0">收集结果{{item.block_number}}条</div>
            <div class="vote_score_title" v-if="item.block_number<=0">暂无收集数据</div>
            <div class="vote_score_star" v-if="item.block_number>0">
              <el-row>
                <el-col :span="1">
                  平均分：
                </el-col>
                <el-col :span="23">
                  <el-rate
                    :value="proportion_num(item.average)"
                    disabled
                    show-score
                    text-color="#ff9900"
                    disabled-void-color='#C0C4CC'
                    score-template="{value}">
                  </el-rate>
                </el-col>
              </el-row>
            </div>
          </div>
        </div>
      </div>


    </div>
    <el-dialog
      title="提示"
      :visible.sync="dialogVisible"
      width="30%"
      :show-close="false"
      :close-on-click-modal="false"
      :close-on-press-escape="false"
    >
      <el-row>
        <el-col :span="3">
          <i class="el-icon-loading" style="font-size: 30px"></i>
        </el-col>
        <el-col :span="21">
          <div>加载中,请耐心等待,数量越多时间越长。</div>
<!--          <div>若长时间未成功导出，建议调整筛选条件减少导出数，然后分多次导出。</div>-->
        </el-col>
      </el-row>
    </el-dialog>
  </div>

</template>

