    methods: {
      export_vote: function() {
        this.export_vote()
      },
      // 导出
      async export_vote() {
        let param = {
          vote_id: this.vote_id
        }
        let _this = this;
        _this.dialogVisible = true;
        let res = await this.$api.exportVote(param);
        this.loading = false;
        console.log('export_vote', res);
        if (res && res.export_id) {
          _this.export_id = res.export_id;
          _this.downloadExportFile()
        }
      },
      // 导出
      async downloadExportFile() {
        let param = {
          export_id: this.export_id
        }
        let _this = this;
        console.log('param', param);
        let res = await this.$api.downloadExportFile(param);
        if (res && res.export_id) {
          console.log('downloadExportFile', res.export_id);
          _this.dialogVisible = false;
          location.href = '/plugin.php?plugin=vote&from=house&c=Index&a=download_export_file&export_id='+this.export_id;
        }else{
          setTimeout(function () {
            _this.downloadExportFile();
          },1000);
        }
      },
      // 获取投票详情
      async statisticalVoteDetail() {
        let param = {
          vote_id: this.vote_id
        }
        let res = await this.$api.statisticalVoteDetail(param);
        this.loading = false;
        if (res) {
          console.log(`res: `, res);
          this.vote_detail = res;
        }
      },
      return_vote_list: function () {
        this.$router.replace({ path: '/vote_list'});
      },
      proportion_num: function(num) {
        return parseFloat(num)
      },
      vote_sort: function (index) {
        return parseInt(index) + 1
      },
      look_detail: function (block_id) {
        console.log('block_id', block_id);
        this.$router.replace({ path: '/vote_join_detail', query: { block_id: block_id }});
      },
      getSummaries: function (param) {
        const { columns, data } = param;
        const sums = [];
        columns.forEach((column, index) => {
          if (index === 0) {
            sums[index] = '本题有效填写人次';
            return;
          }
          if (index === 1) {
            const values = data.map(item => Number(item['option_number']));
            console.log(values);
            sums[index] = values.reduce((prev, curr) => {
              const value = Number(curr);
              if (!isNaN(value)) {
                return prev + curr;
              } else {
                return prev;
              }
            }, 0);
          }
        });

        return sums;
      }
