    position: fixed;
    top: 0;
    z-index: 9999;
  }
  .vote_statistics_box .vote_statistics_content {
    padding: 55px 30px 40px;
    clear: both;
  }
  .vote_statistics_box .vote_statistics_title {
    font-size: 14px;
    line-height: 40px;
  }
  .vote_statistics_box .vote_statistics_export {
    text-align: right;
  }
  .vote_statistics_box .vote_statistics_vote_content {
    padding: 20px 0;
