    margin-bottom: 20px;
  }
  .vote_statistics_box .vote_statistics_data {
    margin-top: 10px;
  }
  .vote_statistics_box .vote_statistics_data.table_info {
    border-top: 1px solid #ebeef5;
    border-left: 1px solid #ebeef5;
    border-right: 1px solid #ebeef5;
  }

  .vote_statistics_box .vote_score_title {
    font-size: 13px;
    color: #666;
  }
  .vote_statistics_box .vote_score_star {
    padding-top: 10px;
    font-size: 13px;
  }
</style>
